args.command:
cd /tmp/mel05
t() { printf '%s' "$1" | /workspace/executable 2>&1; echo " EXIT:$?"; }
echo -n '--- nota to z => '; t 'nota to z;'
echo -n '--- either no spaces => '; t 'either{"a";"b";}'
echo -n '--- t to z => '; t 'ttoz;'
echo '--- multiline error line no:'; t 'either {
  "a";
  %
}'
echo -n '--- block comment inside range => '; t 'a /* c */ to /* c */ z;'
echo -n '--- either only not space => '; t 'either { not <space>; }'
echo -n '--- nested block comment => '; t '/* a /* b */ "x";'
echo -n '--- unterminated comment => '; t '/* abc'

result.output:
either { '\\'; }
(?:\\)
EXIT:0
